/* 64-bit FNV-1a Hash */
static inline uint64_t we_fnv1a_64_slug(const char *str, size_t len)
{
    uint64_t h = 0xcbf29ce484222325ULL;
    for (size_t i = 0; i < len; i++) {
        h = (h ^ (uint8_t)str[i]) * 0x100000001b3ULL;
    }
    return h ? h : 1;
}

static void normalize_slug(const char *src, char *dst, size_t dst_cap)
{
    if (!src || !dst || dst_cap == 0)
        return;
    const char *p = src;
    if (strncmp(p, "shaders/", 8) == 0)
        p += 8;
    else if (strncmp(p, "/shaders/", 9) == 0)
        p += 9;
    if (strncmp(p, "effects/", 8) == 0)
        p += 8;
    else if (strncmp(p, "/effects/", 9) == 0)
        p += 9;

    const char *slash = strrchr(p, '/');
    const char *bslash = strrchr(p, '\\');
    if (bslash && (!slash || bslash > slash))
        slash = bslash;
    if (slash) {
        /* If directory path like waterwaves/waterwaves.frag or waterwaves/shaders/... */
        const char *first_slash = strchr(p, '/');
        const char *first_bslash = strchr(p, '\\');
        if (first_bslash && (!first_slash || first_bslash < first_slash))
            first_slash = first_bslash;
        if (first_slash && first_slash > p) {
            size_t dir_len = (size_t)(first_slash - p);
            if (dir_len < dst_cap) {
                /* Try directory name first as slug if slash is present */
                size_t d = 0;
                for (size_t i = 0; i < dir_len && d + 1 < dst_cap; i++) {
                    char c = p[i];
                    if (c == '-' || c == '.')
                        c = '_';
                    dst[d++] = (char)tolower((unsigned char)c);
                }
                dst[d] = '\0';
                /* If dir is not 'shaders' or 'effects', it is the slug! */
                if (strcmp(dst, "shaders") != 0 && strcmp(dst, "effects") != 0) {
                    return;
                }
            }
        }
        p = slash + 1;
    }

    size_t d = 0;
    while (*p && *p != '.' && d + 1 < dst_cap) {
        char c = *p++;
        if (c == '-')
            c = '_';
        dst[d++] = (char)tolower((unsigned char)c);
    }
    dst[d] = '\0';
}

const we_builtin_effect_desc_t *we_builtin_effects_get_table(size_t *out_count)
{
    if (out_count)
        *out_count = WE_BUILTIN_EFFECT_COUNT;
    return s_we_builtin_table;
}

const we_builtin_effect_desc_t *we_builtin_effect_get_by_id(we_builtin_effect_id_t id)
{
    if (id >= 1 && id <= WE_BUILTIN_EFFECT_COUNT) {
        return &s_we_builtin_table[id - 1];
    }
    return NULL;
}

const we_builtin_effect_desc_t *we_builtin_effect_find_by_id(we_builtin_effect_id_t id)
{
    return we_builtin_effect_get_by_id(id);
}

const we_builtin_effect_desc_t *we_builtin_effect_find_by_slug(const char *slug_or_path)
{
    if (!slug_or_path || slug_or_path[0] == '\0')
        return NULL;
    char norm[64];
    normalize_slug(slug_or_path, norm, sizeof(norm));
    if (norm[0] == '\0')
        return NULL;

    size_t len = strlen(norm);
    uint64_t h = we_fnv1a_64_slug(norm, len);
    uint32_t mask = 255u;
    uint32_t idx = (uint32_t)(h & mask);
    uint32_t psl = 0;

    for (;;) {
        const we_rh_entry_t *e = &s_rh_table[idx];
        if (e->hash == 0 || psl > e->psl) {
            break;
        }
        if (e->hash == h && e->slug && strcmp(e->slug, norm) == 0) {
            return we_builtin_effect_get_by_id((we_builtin_effect_id_t)e->effect_id);
        }
        psl++;
        idx = (idx + 1) & mask;
    }

    /* Fallback: linear check on canonical slugs if alias had non-standard characters */
    for (uint32_t i = 0; i < WE_BUILTIN_EFFECT_COUNT; i++) {
        if (strcasecmp(s_we_builtin_table[i].slug, norm) == 0) {
            return &s_we_builtin_table[i];
        }
    }
    return NULL;
}

size_t we_builtin_effect_decompress_glsl(we_builtin_effect_id_t id, char *out_buf,
                                         size_t out_buf_cap)
{
    return we_builtin_effect_decompress_stage(id, true, out_buf, out_buf_cap);
}

size_t we_builtin_effect_decompress_stage(we_builtin_effect_id_t id, bool is_frag, char *out_buf,
                                          size_t out_buf_cap)
{
    const we_builtin_effect_desc_t *desc = we_builtin_effect_get_by_id(id);
    if (!desc || !out_buf || out_buf_cap == 0)
        return 0;

    char temp[8192];
    size_t decomp = we_lz4_decompress_block(s_we_builtin_lz4_blob + desc->lz4_compressed_offset,
                                            desc->lz4_compressed_size, temp, sizeof(temp));
    if (decomp < 4 || decomp >= sizeof(temp))
        return 0;

    uint32_t vert_len = (uint32_t)((uint8_t)temp[0] | ((uint8_t)temp[1] << 8) |
                                   ((uint8_t)temp[2] << 16) | ((uint8_t)temp[3] << 24));
    if (4u + vert_len > decomp)
        return 0;

    const char *v_src = temp + 4;
    const char *f_src = temp + 4 + vert_len;
    size_t f_len = decomp - (4u + vert_len);

    const char *stage_src = is_frag ? f_src : v_src;
    size_t stage_len = is_frag ? f_len : vert_len;
    if (stage_len + 1 > out_buf_cap) {
        stage_len = out_buf_cap - 1;
    }
    size_t max_avail = (size_t)((temp + sizeof(temp)) - stage_src);
    if (stage_len > max_avail) {
        stage_len = max_avail;
    }
    memcpy(out_buf, stage_src, stage_len);
    out_buf[stage_len] = '\0';
    return stage_len;
}

/* Decompressed static cache for fast pointer-based return in we_shader_get_builtin */
static char s_stage_cache[WE_BUILTIN_EFFECT_COUNT][2][4096];
static bool s_stage_cached[WE_BUILTIN_EFFECT_COUNT][2];

const char *we_builtin_effect_get_stage_glsl(we_builtin_effect_id_t id, bool is_frag)
{
    if (id < 1 || id > WE_BUILTIN_EFFECT_COUNT)
        return NULL;
    uint32_t idx = id - 1;
    uint32_t stage = is_frag ? 1 : 0;
    if (!s_stage_cached[idx][stage]) {
        size_t n = we_builtin_effect_decompress_stage(id, is_frag, s_stage_cache[idx][stage],
                                                      sizeof(s_stage_cache[idx][stage]));
        if (n == 0)
            return NULL;
        s_stage_cached[idx][stage] = true;
    }
    return s_stage_cache[idx][stage];
}
